<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';
require_once DOGOFLOW_ROOT . '/core/catalog/StoreArt.php';
$q = trim((string)($_GET['q'] ?? ''));
$category = trim((string)($_GET['category'] ?? ''));
$sql = "SELECT sp.*, COUNT(DISTINCT p.id) AS product_count FROM seller_profiles sp JOIN users u ON u.id=sp.user_id AND u.role='seller' AND u.status='active' LEFT JOIN products p ON p.seller_id=sp.user_id AND p.status='active' LEFT JOIN seller_categories sc ON sc.seller_id=sp.user_id LEFT JOIN categories c ON c.id=sc.category_id AND c.status='active' WHERE sp.status='active' AND sp.approval_status='approved'";
$params=[];
if ($q !== '') { $sql .= " AND (sp.business_name LIKE :q_name OR sp.store_description LIKE :q_desc OR sp.store_location LIKE :q_loc)"; $params['q_name']=$params['q_desc']=$params['q_loc']='%'.$q.'%'; }
if ($category !== '') { $sql .= " AND c.slug=:category"; $params['category']=$category; }
$sql .= " GROUP BY sp.id ORDER BY sp.business_name LIMIT 48";
$stmt=db()->prepare($sql); $stmt->execute($params); $stores=$stmt->fetchAll(PDO::FETCH_ASSOC);
$categories=db()->query("SELECT DISTINCT c.name,c.slug FROM categories c JOIN seller_categories sc ON sc.category_id=c.id WHERE c.status='active' ORDER BY c.name")->fetchAll(PDO::FETCH_ASSOC);
?>
