t3-filter-fab{display:flex!important;position:fixed;z-index:100;right:16px;bottom:18px;align-items:center;gap:8px;border:0;border-radius:999px;padding:14px 18px;background:#0088ee;color:#fff;font-weight:900;box-shadow:0 12px 32px #0088ee55}}@media(min-width:901px){.st3-filter-fab,.st3-filter-backdrop{display:none!important}}@media(max-width:600px){.st3-links a:not(.st3-login):not(:nth-child(1)):not(:nth-child(2)){display:none}.st3-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.st3-card{border-radius:14px}.st3-cover{height:125px}.st3-content{padding:12px}.st3-hero{padding:30px 0 18px}.st3-hero p{font-size:.9rem}.st3-search{grid-template-columns:1fr}}
.st3-cover:after{background:#fff!important;color:#334155!important;border:1px solid #E2E8F0!important;box-shadow:0 4px 12px rgba(15,23,42,.08)}.df-store-id{position:absolute;top:12px;right:12px;z-index:2;background:#fff;color:#0B5CFF;font-weight:800;font-size:12px;letter-spacing:.04em;padding:6px 12px;border-radius:999px;border:1px solid #DBEAFE;box-shadow:0 4px 12px rgba(15,23,42,.12)}</style><style>.st3-hero{background:linear-gradient(135deg,#020617 0%,#0F172A 55%,#075985 100%)!important;border-radius:0}.st3-eyebrow{color:#7DD3FC!important}.st3-hero h1{color:#fff!important}.st3-hero p{color:#CBD5E1!important}</style></head><body class="st3"><header class="st3-nav"><div class="wrap"><a href="<?= e(url('/')) ?>"><img src="<?= e(url('/assets/images/df-logo.png')) ?>" alt="DogoFlow"></a><nav class="st3-links"><a href="<?= e(url('/products.php')) ?>">Products</a><a href="<?= e(url('/stores.php')) ?>">Stores</a><a href="<?= e(url('/auth/login.php')) ?>" class="st3-login">Login</a><a href="<?= e(url('/auth/register.php')) ?>">Create account</a></nav></div></header><div class="st3-filter-backdrop" id="stFilterBackdrop"></div><button class="st3-filter-fab" id="stFilterOpen" type="button" aria-controls="stStoreFilters" aria-expanded="false" style="display:none"><span>☷</span> Filters</button><section class="st3-hero"><div class="wrap"><span class="st3-eyebrow">DogoFlow Marketplace</span><h1>Explore Stores</h1><p>Browse approved stores and shop directly from them.</p><form method="get" class="st3-search" id="stStoreFilters"><button class="st3-filter-close" id="stFilterClose" type="button">✕ Close filters</button><label>Search stores<input name="q" value="<?= e($q) ?>" placeholder="Store name or location"></label><label>Category<select name="category"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?= e($c['slug']) ?>" <?= $category===$c['slug']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><button type="submit">Search stores</button></form></div></section><main class="wrap st3-grid"><?php foreach($stores as $s): $slug=(string)($s['store_slug']?:strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',(string)$s['business_name']),'-'))); $logo=trim((string)($s['store_logo']??'')); $banner=trim((string)($s['store_banner']??'')); ?><article class="st3-card"><div class="st3-cover"><?php if($banner!==''): ?><img src="<?= e(url('/'.ltrim($banner,'/'))) ?>" alt="<?= e($s['business_name']) ?> cover" loading="lazy"><?php else: ?><img src="<?= e(StoreArt::cover($slug.'|'.(string)($s['seller_code']??''), (string)$s['business_name'])) ?>" alt="" loading="lazy"><?php endif; ?><?php if (!empty($s['seller_code'])): ?><span class="df-store-id">Store ID <?= e((string) $s['seller_code']) ?></span><?php endif; ?></div><div class="st3-content"><?php if($logo!==''): ?><img class="st3-logo" src="<?= e(url('/'.ltrim($logo,'/'))) ?>" alt="<?= e($s['business_name']) ?> logo" loading="lazy"><?php endif; ?><h2><?= e($s['business_name']) ?></h2><div class="st3-meta"><?= e((string)($s['store_location']??'Location not provided')) ?><br><?= (int)$s['product_count'] ?> published products</div><div class="st3-actions"><a href="<?= e(url('/store.php?slug='.urlencode($slug))) ?>">Visit store →</a></div></div></article><?php endforeach; ?><?php if(!$stores): ?><div class="st3-empty">No stores matched your search. Try another name or category.</div><?php endif; ?></main><?php require __DIR__ . '/includes/footer.php'; ?><script>(function(){const panel=document.getElementById('stStoreFilters'),backdrop=document.getElementById('stFilterBackdrop'),open=document.getElementById('stFilterOpen'),close=document.getElementById('stFilterClose');if(!panel||!backdrop||!open)return;function setOpen(v){panel.classList.toggle('open',v);backdrop.classList.toggle('open',v);open.setAttribute('aria-expanded',v?'true':'false');document.body.style.overflow=v?'hidden':'';}open.addEventListener('click',()=>setOpen(!panel.classList.contains('open')));if(close)close.addEventListener('click',()=>setOpen(false));backdrop.addEventListener('click',()=>setOpen(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')setOpen(false)});})();</script></body></html>